// Disposable browser acceleration, never a source of truth. A checkpoint is
// reused only after its block hash is checked against the current chain.
import { SCHEMA_HASH } from './generated/index.js';
import { contractInterface, compareLogs, logKey, checkAbort } from './client.js';

const memory = new Map();
const MAX_BYTES = 16 * 1024 * 1024;
let database;
function openCache() {
  if (!globalThis.indexedDB) return Promise.resolve(null);
  if (!database) database = new Promise(resolve => {
    const request = indexedDB.open('degenerus-chain-cache-v1', 1);
    request.onupgradeneeded = () => request.result.createObjectStore('reads', { keyPath: 'key' });
    request.onsuccess = () => resolve(request.result);
    request.onerror = request.onblocked = () => resolve(null);
  });
  return database;
}
async function diskGet(key) {
  try {
    const db = await openCache(); if (!db) return null;
    return await new Promise(resolve => {
      const req = db.transaction('reads').objectStore('reads').get(key);
      req.onsuccess = () => resolve(req.result?.value ?? null); req.onerror = () => resolve(null);
    });
  } catch { return null; }
}
async function diskPut(key, value, bytes) {
  try {
    const db = await openCache(); if (!db) return;
    await new Promise(resolve => {
      const tx = db.transaction('reads', 'readwrite'); const store = tx.objectStore('reads');
      store.put({ key, value, bytes, touched: Date.now() });
      const all = store.getAll();
      all.onsuccess = () => {
        const rows = all.result.sort((a, b) => b.touched - a.touched); let total = 0;
        for (const row of rows) { total += row.bytes; if (total > MAX_BYTES) store.delete(row.key); }
      };
      tx.oncomplete = tx.onerror = tx.onabort = () => resolve();
    });
  } catch { /* Private browsing/quota failure simply loses acceleration. */ }
}
function remember(key, value) {
  const bytes = JSON.stringify(value).length * 2;
  if (bytes > MAX_BYTES / 2) return;
  memory.delete(key); memory.set(key, { value, bytes });
  let total = [...memory.values()].reduce((n, item) => n + item.bytes, 0);
  for (const [oldKey, item] of memory) { if (total <= MAX_BYTES / 2) break; memory.delete(oldKey); total -= item.bytes; }
  void diskPut(key, value, bytes);
}
export async function cachedLogs(snapshot, filter, { fromBlock, toBlock, signal } = {}) {
  const client = snapshot.client; const start = Number(fromBlock ?? client.chain.deployBlock);
  const upper = toBlock != null && Number(toBlock) < snapshot.block.number ? await client.header(Number(toBlock), signal) : snapshot.block;
  if (start > upper.number) return [];
  const key = JSON.stringify([SCHEMA_HASH, client.chain.id, client.address('GAME'), filter, start]);
  let checkpoint = memory.get(key)?.value ?? await diskGet(key);
  checkAbort(signal);
  if (checkpoint) {
    if (checkpoint.number > upper.number) checkpoint = null;
    else {
      const block = checkpoint.number === upper.number ? upper : await client.header(checkpoint.number, signal);
      if (block.hash !== checkpoint.hash) checkpoint = null;
    }
  }
  if (checkpoint?.number === upper.number) return checkpoint.logs;
  const accumulated = [...(checkpoint?.logs ?? [])]; let receivedPage = false;
  const tail = await client.logs(filter, { fromBlock: checkpoint ? checkpoint.number + 1 : start, toBlock: upper.number, signal,
    onPage: async (page, range) => {
      receivedPage = true; accumulated.push(...page);
      if (range.toBlock < upper.number) {
        // Save verified progress before the next RPC. A slow cold recovery can
        // resume after cancellation instead of repeating its completed pages.
        const block = await client.header(range.toBlock, signal);
        await snapshot.verify(signal);
        remember(key, { number: block.number, hash: block.hash, logs: [...accumulated] });
      }
    },
  });
  if (!receivedPage) accumulated.push(...tail);
  const logs = [...new Map(accumulated.map(log => [logKey(log), log])).values()].sort(compareLogs);
  // Raw RPC values are JSON-safe; decoding happens after cache retrieval.
  remember(key, { number: upper.number, hash: upper.hash, logs });
  return logs;
}
export async function cachedEvents(snapshot, name, eventName, filters = {}, options = {}) {
  const iface = await contractInterface(name); const fragment = iface.getEvent(eventName);
  const topics = iface.encodeFilterTopics(fragment, fragment.inputs.map(input => input.indexed ? filters[input.name] ?? null : null));
  const logs = await cachedLogs(snapshot, { address: snapshot.client.address(name), topics }, options);
  return logs.map(log => ({ ...log, name: eventName, args: iface.decodeEventLog(fragment, log.data, log.topics) }));
}

// Seek the nearest relevant event/transaction instead of downloading all game
// days. The result includes the complete boundary block so log ordering holds.
export async function previousEvents(client, name, eventName, before, { filters = {}, signal, accept = () => true } = {}) {
  let end = Number(before.blockNumber); const lower = Number(client.chain.deployBlock);
  let span = 2_000;
  while (end >= lower) {
    checkAbort(signal); const start = Math.max(lower, end - span + 1);
    const logs = (await client.events(name, eventName, filters, { fromBlock: start, toBlock: end, initialSpan: span, signal }))
      .filter(log => compareLogs(log, before) < 0 && accept(log));
    if (logs.length) {
      const last = logs.at(-1);
      return logs.filter(log => log.transactionHash === last.transactionHash);
    }
    end = start - 1;
    span = Math.min(1_000_000, span * 4);
  }
  return [];
}

export function clearEventMemoryForTests() { memory.clear(); }

export async function readArtifact(key) {
  const full = `artifact:${SCHEMA_HASH}:${key}`;
  return memory.get(full)?.value ?? await diskGet(full);
}
export function writeArtifact(key, value) { remember(`artifact:${SCHEMA_HASH}:${key}`, value); }
